var i=`0034-zurek`;var t=`world-0034`;var n=`PL`;var r=`eastern-europe`;var o=4;var s=54;var u={en:`Żurek`,ua:`Журек`};var m={en:`A classic dish from Poland, featuring ukrainian homemade sausage, bay leaf, yellow onion, garlic. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Польща. Основні складники: українська домашня ковбаса, лавровий лист, жовта цибуля, часник. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 25 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 25 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:25,i:[[`ukrainian-homemade-sausage`,280,`g`],[`water`,1150,`ml`],[`bay-leaf`,2,`leaf`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,120,`g`],[`garlic`,3,`clove`],[`lard`,20,`g`]]},{en:`Whisk rye sourdough starter and rye flour with some hot broth until smooth. Gradually stir the sour mixture into the sausage broth and simmer gently for 7 minutes; do not treat this as a butter roux.`,ua:`Розведіть житню закваску й житнє борошно частиною гарячого бульйону до однорідності. Поступово влийте кислу суміш у бульйон із ковбасою та проваріть 7 хвилин; це не масляна засмажка.`,t:[`sourdough-fermentation`,`simmering`],m:7,i:[[`rye-flour`,35,`g`],[`rye-sourdough-starter`,140,`g`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,4,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`dried-marjoram`,3,`g`],[`sour-cream`,120,`g`],[`table-salt`,null,`to_taste`]]}];var l={slug:i,id:t,country:`PL`,region:r,servings:4,minutes:54,title:u,text:m,steps:g};export{n as country,l as default,t as id,s as minutes,r as region,o as servings,i as slug,g as steps,m as text,u as title};